/* Payload keeps two generated files in the repo: the admin importMap and the
   TypeScript types. Neither is regenerated by `next build`, and a stale
   importMap does NOT fail the build, does not change the rendered HTML, and
   does not alter any HTTP status — it surfaces only as a server-side console
   error when the admin loads. That is how a broken /admin once passed build,
   typecheck, smoke and fingerprint simultaneously.

   So this check does not probe the running app. It regenerates both files and
   asserts nothing changed, which is the only deterministic way to catch it. */
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";

const FILES = [
  ["src/app/(payload)/admin/importMap.js", "generate:importmap"],
  ["src/payload-types.ts", "generate:types"],
];

let failures = 0;
const before = FILES.map(([f]) => readFileSync(f, "utf8"));

for (const [, cmd] of FILES) {
  execFileSync("npx", ["payload", cmd.split(":")[0] + ":" + cmd.split(":")[1]], { stdio: "ignore" });
}

FILES.forEach(([file], i) => {
  const after = readFileSync(file, "utf8");
  if (after !== before[i]) {
    console.error(`FAIL  ${file} is out of date — regenerating it changed the file.`);
    console.error(`      Run: npm run ${FILES[i][1]}   then commit the result.`);
    failures++;
  } else {
    console.log(`ok    ${file} is up to date`);
  }
});

process.exit(failures === 0 ? 0 : 1);
